-- Non-destructive installation. All application objects live in schoolnet.
CREATE SCHEMA IF NOT EXISTS schoolnet;
SET search_path TO schoolnet, public;
CREATE TABLE IF NOT EXISTS schema_version(version integer PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS app_user(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, username text NOT NULL UNIQUE,
 name text NOT NULL, password_hash text NOT NULL, role text NOT NULL CHECK(role IN ('Administrator','Coordinator','Trainer','Trainee')),
 active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS project(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code text NOT NULL UNIQUE, name text NOT NULL,
 description text NOT NULL DEFAULT '', active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS user_project(user_id bigint REFERENCES app_user, project_id bigint REFERENCES project, PRIMARY KEY(user_id,project_id));
CREATE TABLE IF NOT EXISTS location(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name text NOT NULL, kind text NOT NULL CHECK(kind IN ('State','District','Block','Cluster')),
 parent_id bigint REFERENCES location, UNIQUE(name,kind,parent_id));
CREATE TABLE IF NOT EXISTS school(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code text NOT NULL UNIQUE, name text NOT NULL,
 cluster_id bigint NOT NULL REFERENCES location, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS project_school(project_id bigint REFERENCES project, school_id bigint REFERENCES school, PRIMARY KEY(project_id,school_id));
CREATE TABLE IF NOT EXISTS trainee(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, username text NOT NULL UNIQUE CHECK(username=lower(btrim(username))),
 name text NOT NULL, mobile text NOT NULL CHECK(mobile ~ '^\+?[0-9]{10,15}$'), email text NOT NULL CHECK(email ~ '^[^ @]+@[^ @]+\.[^ @]+$'),
 project_id bigint NOT NULL REFERENCES project, school_id bigint NOT NULL REFERENCES school, user_id bigint UNIQUE REFERENCES app_user,
 active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS feedback_template(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name text NOT NULL,
 version_number integer NOT NULL DEFAULT 1 CHECK(version_number>0), source_id bigint REFERENCES feedback_template,
 questions jsonb NOT NULL CHECK(jsonb_typeof(questions)='array'), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS trainingplan(training_plan_id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, plan_code text NOT NULL, plan_name text NOT NULL,
 number_of_days integer NOT NULL CHECK(number_of_days BETWEEN 2 AND 365), description text NOT NULL DEFAULT '', version_number integer NOT NULL DEFAULT 1 CHECK(version_number>0),
 source_training_plan_id bigint REFERENCES trainingplan, status text NOT NULL DEFAULT 'Draft' CHECK(status IN ('Draft','Published','Archived')),
 created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(plan_code,version_number));
CREATE TABLE IF NOT EXISTS trainingplandetails(training_plan_detail_id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 training_plan_id bigint NOT NULL REFERENCES trainingplan, day_number integer NOT NULL CHECK(day_number>0),
 activity_type text NOT NULL CHECK(activity_type IN ('Feedback','Classroom training')), title text NOT NULL,
 topics text NOT NULL DEFAULT '', instructions text NOT NULL DEFAULT '', feedback_template_version_id bigint REFERENCES feedback_template,
 duration_minutes integer CHECK(duration_minutes>0), UNIQUE(training_plan_id,day_number));
CREATE TABLE IF NOT EXISTS batch(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code text NOT NULL UNIQUE, name text NOT NULL,
 project_id bigint NOT NULL REFERENCES project, school_id bigint NOT NULL REFERENCES school,
 training_plan_id bigint NOT NULL REFERENCES trainingplan, number_of_days integer NOT NULL CHECK(number_of_days>=2),
 start_date date NOT NULL, end_date date NOT NULL, trainer_id bigint REFERENCES app_user,
 status text NOT NULL DEFAULT 'Draft' CHECK(status IN ('Draft','Scheduled','In progress','Completed','Cancelled')),
 cancellation_reason text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(),
 CHECK(end_date=start_date+number_of_days-1));
CREATE TABLE IF NOT EXISTS batch_assignment(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, batch_id bigint NOT NULL REFERENCES batch,
 trainee_id bigint NOT NULL REFERENCES trainee, project_id bigint NOT NULL REFERENCES project, school_id bigint NOT NULL REFERENCES school,
 assigned_by bigint NOT NULL REFERENCES app_user, assigned_at timestamptz NOT NULL DEFAULT now(), UNIQUE(batch_id,trainee_id));
CREATE TABLE IF NOT EXISTS attendance(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, assignment_id bigint NOT NULL REFERENCES batch_assignment,
 training_plan_detail_id bigint NOT NULL REFERENCES trainingplandetails,
 status text NOT NULL DEFAULT 'Not marked' CHECK(status IN ('Present','Absent','Not marked')), remarks text NOT NULL DEFAULT '',
 marked_by bigint REFERENCES app_user, marked_at timestamptz, revision integer NOT NULL DEFAULT 0, UNIQUE(assignment_id,training_plan_detail_id));
CREATE TABLE IF NOT EXISTS feedback_submission(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 assignment_id bigint NOT NULL REFERENCES batch_assignment, training_plan_detail_id bigint NOT NULL REFERENCES trainingplandetails,
 template_version_id bigint NOT NULL REFERENCES feedback_template, answers jsonb NOT NULL,
 submitted_by bigint NOT NULL REFERENCES app_user, submitted_at timestamptz NOT NULL DEFAULT now(), reason text,
 UNIQUE(assignment_id,training_plan_detail_id));
CREATE TABLE IF NOT EXISTS audit_log(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, entity text NOT NULL, record_id text,
 action text NOT NULL, actor_id bigint REFERENCES app_user, old_data jsonb, new_data jsonb, reason text, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_batch_project ON batch(project_id,status,start_date);
CREATE INDEX IF NOT EXISTS idx_assignment_trainee ON batch_assignment(trainee_id);
CREATE INDEX IF NOT EXISTS idx_attendance_assignment ON attendance(assignment_id);
CREATE INDEX IF NOT EXISTS idx_trainee_scope ON trainee(project_id,school_id);

CREATE OR REPLACE VIEW school_directory AS
 SELECT s.*, c.name cluster, b.name block, d.name district, st.name state, st.id state_id, d.id district_id, b.id block_id
 FROM school s JOIN location c ON c.id=s.cluster_id JOIN location b ON b.id=c.parent_id JOIN location d ON d.id=b.parent_id JOIN location st ON st.id=d.parent_id;
CREATE OR REPLACE VIEW batch_directory AS
 SELECT b.*, p.name project, s.name school, s.state, s.state_id, tp.plan_name, tp.version_number, u.name trainer,
 CASE WHEN b.status='Scheduled' AND b.start_date <= (now() AT TIME ZONE 'Asia/Kolkata')::date THEN 'In progress' ELSE b.status END display_status,
 (SELECT count(*) FROM batch_assignment a WHERE a.batch_id=b.id) trainees,
 (SELECT count(*) FROM attendance t JOIN batch_assignment a ON a.id=t.assignment_id WHERE a.batch_id=b.id AND t.status='Not marked') unmarked,
 (SELECT count(*) FROM feedback_submission f JOIN batch_assignment a ON a.id=f.assignment_id JOIN trainingplandetails d ON d.training_plan_detail_id=f.training_plan_detail_id WHERE a.batch_id=b.id AND d.day_number=1) initial_feedback,
 (SELECT count(*) FROM feedback_submission f JOIN batch_assignment a ON a.id=f.assignment_id JOIN trainingplandetails d ON d.training_plan_detail_id=f.training_plan_detail_id WHERE a.batch_id=b.id AND d.day_number=b.number_of_days) final_feedback
 FROM batch b JOIN project p ON p.id=b.project_id JOIN school_directory s ON s.id=b.school_id JOIN trainingplan tp ON tp.training_plan_id=b.training_plan_id LEFT JOIN app_user u ON u.id=b.trainer_id;

CREATE OR REPLACE FUNCTION actor_role(p_actor bigint) RETURNS text LANGUAGE sql STABLE AS $$ SELECT role FROM schoolnet.app_user WHERE id=p_actor AND active $$;
CREATE OR REPLACE FUNCTION can_project(p_actor bigint,p_project bigint) RETURNS boolean LANGUAGE sql STABLE AS $$
 SELECT coalesce(schoolnet.actor_role(p_actor)='Administrator' OR (schoolnet.actor_role(p_actor)='Coordinator' AND EXISTS(SELECT 1 FROM schoolnet.user_project WHERE user_id=p_actor AND project_id=p_project)),false) $$;
CREATE OR REPLACE FUNCTION can_batch(p_actor bigint,p_batch bigint) RETURNS boolean LANGUAGE sql STABLE AS $$
 SELECT coalesce(EXISTS(SELECT 1 FROM schoolnet.batch b WHERE b.id=p_batch AND (schoolnet.can_project(p_actor,b.project_id) OR (schoolnet.actor_role(p_actor)='Trainer' AND b.trainer_id=p_actor) OR (schoolnet.actor_role(p_actor)='Trainee' AND EXISTS(SELECT 1 FROM schoolnet.batch_assignment a JOIN schoolnet.trainee t ON t.id=a.trainee_id WHERE a.batch_id=b.id AND t.user_id=p_actor)))),false) $$;
CREATE OR REPLACE FUNCTION require_admin(p_actor bigint) RETURNS void LANGUAGE plpgsql AS $$ BEGIN IF schoolnet.actor_role(p_actor) IS DISTINCT FROM 'Administrator' THEN RAISE EXCEPTION 'Administrator permission required.'; END IF; END $$;
CREATE OR REPLACE FUNCTION require_project(p_actor bigint,p_project bigint) RETURNS void LANGUAGE plpgsql AS $$ BEGIN IF NOT schoolnet.can_project(p_actor,p_project) THEN RAISE EXCEPTION 'You do not have permission for this project.'; END IF; END $$;
CREATE OR REPLACE FUNCTION set_actor(p_actor bigint,p_reason text DEFAULT '') RETURNS void LANGUAGE plpgsql AS $$ BEGIN
 IF schoolnet.actor_role(p_actor) IS NULL THEN RAISE EXCEPTION 'Active user required.'; END IF;
 PERFORM set_config('schoolnet.actor',p_actor::text,true); PERFORM set_config('schoolnet.reason',coalesce(p_reason,''),true); END $$;
CREATE OR REPLACE FUNCTION audit_change() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 INSERT INTO schoolnet.audit_log(entity,record_id,action,actor_id,old_data,new_data,reason)
 VALUES(TG_TABLE_NAME,coalesce(to_jsonb(NEW)->>'id',to_jsonb(NEW)->>'training_plan_id',to_jsonb(OLD)->>'id',to_jsonb(OLD)->>'training_plan_id'),TG_OP,
 nullif(current_setting('schoolnet.actor',true),'')::bigint,to_jsonb(OLD)-'password_hash',to_jsonb(NEW)-'password_hash',current_setting('schoolnet.reason',true));
 IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW; END $$;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['app_user','project','school','project_school','trainee','location','feedback_template','trainingplan','trainingplandetails','batch','batch_assignment','attendance','feedback_submission'] LOOP
 EXECUTE format('DROP TRIGGER IF EXISTS audit_changes ON schoolnet.%I',t);
 EXECUTE format('CREATE TRIGGER audit_changes AFTER INSERT OR UPDATE OR DELETE ON schoolnet.%I FOR EACH ROW EXECUTE FUNCTION schoolnet.audit_change()',t);
END LOOP; END $$;

CREATE OR REPLACE FUNCTION protect_plan() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE p trainingplan; BEGIN
 IF TG_TABLE_NAME='trainingplandetails' THEN
 SELECT * INTO p FROM schoolnet.trainingplan WHERE training_plan_id=coalesce(OLD.training_plan_id,NEW.training_plan_id);
 IF p.status<>'Draft' OR EXISTS(SELECT 1 FROM schoolnet.batch WHERE training_plan_id=p.training_plan_id) THEN RAISE EXCEPTION 'Published or referenced plan content is immutable. Create a revision.'; END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF;
 IF NEW.day_number>p.number_of_days OR NEW.activity_type<>(CASE WHEN NEW.day_number IN(1,p.number_of_days) THEN 'Feedback' ELSE 'Classroom training' END) THEN RAISE EXCEPTION 'Activity does not match the numbered plan day.'; END IF;
 ELSE
 IF OLD.status<>'Draft' AND (to_jsonb(NEW)-ARRAY['status','updated_at']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['status','updated_at']) THEN RAISE EXCEPTION 'Published plan content is immutable.'; END IF;
 IF EXISTS(SELECT 1 FROM schoolnet.batch WHERE training_plan_id=OLD.training_plan_id) AND (to_jsonb(NEW)-ARRAY['status','updated_at']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['status','updated_at']) THEN RAISE EXCEPTION 'Referenced plan content is immutable.'; END IF;
 END IF;
 RETURN NEW; END $$;
DROP TRIGGER IF EXISTS protect_plan_content ON trainingplan;
CREATE TRIGGER protect_plan_content BEFORE UPDATE ON trainingplan FOR EACH ROW EXECUTE FUNCTION protect_plan();
DROP TRIGGER IF EXISTS protect_detail_content ON trainingplandetails;
CREATE TRIGGER protect_detail_content BEFORE INSERT OR UPDATE OR DELETE ON trainingplandetails FOR EACH ROW EXECUTE FUNCTION protect_plan();
CREATE OR REPLACE FUNCTION record_integrity() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE b batch; d trainingplandetails; BEGIN
 SELECT ba.* INTO b FROM schoolnet.batch ba JOIN schoolnet.batch_assignment a ON a.batch_id=ba.id WHERE a.id=NEW.assignment_id;
 SELECT * INTO d FROM schoolnet.trainingplandetails WHERE training_plan_detail_id=NEW.training_plan_detail_id;
 IF b.training_plan_id<>d.training_plan_id THEN RAISE EXCEPTION 'Activity belongs to a different training plan.'; END IF;
 IF TG_TABLE_NAME='feedback_submission' THEN
 IF d.activity_type<>'Feedback' OR NEW.template_version_id IS DISTINCT FROM d.feedback_template_version_id THEN RAISE EXCEPTION 'Feedback template does not match this day.'; END IF;
 END IF; RETURN NEW; END $$;
DROP TRIGGER IF EXISTS attendance_integrity ON attendance;
CREATE TRIGGER attendance_integrity BEFORE INSERT OR UPDATE ON attendance FOR EACH ROW EXECUTE FUNCTION record_integrity();
DROP TRIGGER IF EXISTS feedback_integrity ON feedback_submission;
CREATE TRIGGER feedback_integrity BEFORE INSERT OR UPDATE ON feedback_submission FOR EACH ROW EXECUTE FUNCTION record_integrity();
CREATE OR REPLACE FUNCTION check_overlap(p_batch bigint) RETURNS void LANGUAGE plpgsql AS $$ BEGIN
 IF EXISTS(SELECT 1 FROM schoolnet.batch_assignment a JOIN schoolnet.batch b ON b.id=a.batch_id JOIN schoolnet.batch_assignment other ON other.trainee_id=a.trainee_id AND other.batch_id<>b.id JOIN schoolnet.batch ob ON ob.id=other.batch_id
 WHERE b.id=p_batch AND ob.status IN('Scheduled','In progress') AND b.start_date<=ob.end_date AND ob.start_date<=b.end_date) THEN RAISE EXCEPTION 'A trainee has an overlapping scheduled batch.'; END IF; END $$;

CREATE OR REPLACE FUNCTION save_master(p_kind text,p_id bigint,p_data jsonb,p_actor bigint) RETURNS bigint LANGUAGE plpgsql AS $$
DECLARE v_id bigint; v_project bigint; v_school bigint; v_role text; v_parent location; BEGIN
 PERFORM schoolnet.set_actor(p_actor);
 IF p_kind IN('project','school','location','user','template') THEN PERFORM schoolnet.require_admin(p_actor); END IF;
 CASE p_kind
 WHEN 'project' THEN
 IF p_id=0 THEN INSERT INTO schoolnet.project(code,name,description,active) VALUES(btrim(p_data->>'code'),btrim(p_data->>'name'),coalesce(p_data->>'description',''),(p_data->>'active')::boolean) RETURNING id INTO v_id;
 ELSE UPDATE schoolnet.project SET code=btrim(p_data->>'code'),name=btrim(p_data->>'name'),description=coalesce(p_data->>'description',''),active=(p_data->>'active')::boolean,updated_at=now() WHERE id=p_id RETURNING id INTO v_id; END IF;
 WHEN 'location' THEN
 IF p_data->>'kind'<>'State' THEN
 SELECT * INTO v_parent FROM schoolnet.location WHERE id=(p_data->>'parent_id')::bigint;
 IF v_parent.kind IS DISTINCT FROM (CASE p_data->>'kind' WHEN 'District' THEN 'State' WHEN 'Block' THEN 'District' WHEN 'Cluster' THEN 'Block' END) THEN RAISE EXCEPTION 'Select a valid parent location.'; END IF;
 ELSIF nullif(p_data->>'parent_id','') IS NOT NULL THEN RAISE EXCEPTION 'A state cannot have a parent.'; END IF;
 IF p_id<>0 THEN RAISE EXCEPTION 'Create a new location rather than changing an existing hierarchy.'; END IF;
 INSERT INTO schoolnet.location(name,kind,parent_id) VALUES(btrim(p_data->>'name'),p_data->>'kind',nullif(p_data->>'parent_id','')::bigint) RETURNING id INTO v_id;
 WHEN 'school' THEN
 IF NOT EXISTS(SELECT 1 FROM schoolnet.location WHERE id=(p_data->>'cluster_id')::bigint AND kind='Cluster') THEN RAISE EXCEPTION 'A valid cluster is required.'; END IF;
 IF jsonb_array_length(p_data->'projects')=0 THEN RAISE EXCEPTION 'Link the school to at least one project.'; END IF;
 IF p_id<>0 AND EXISTS(SELECT 1 FROM schoolnet.trainee t WHERE t.school_id=p_id AND t.active AND NOT (p_data->'projects') @> to_jsonb(ARRAY[t.project_id])) THEN RAISE EXCEPTION 'Project links are used by active trainees.'; END IF;
 IF p_id<>0 AND EXISTS(SELECT 1 FROM schoolnet.batch b WHERE b.school_id=p_id AND b.status NOT IN('Completed','Cancelled') AND NOT (p_data->'projects') @> to_jsonb(ARRAY[b.project_id])) THEN RAISE EXCEPTION 'Project links are used by active batches.'; END IF;
 IF p_id<>0 AND EXISTS(SELECT 1 FROM schoolnet.trainee WHERE school_id=p_id) AND (SELECT cluster_id FROM schoolnet.school WHERE id=p_id)<>(p_data->>'cluster_id')::bigint THEN RAISE EXCEPTION 'School location is in use by trainee profiles.'; END IF;
 IF p_id=0 THEN INSERT INTO schoolnet.school(code,name,cluster_id,active) VALUES(btrim(p_data->>'code'),btrim(p_data->>'name'),(p_data->>'cluster_id')::bigint,(p_data->>'active')::boolean) RETURNING id INTO v_id;
 ELSE UPDATE schoolnet.school SET code=btrim(p_data->>'code'),name=btrim(p_data->>'name'),cluster_id=(p_data->>'cluster_id')::bigint,active=(p_data->>'active')::boolean,updated_at=now() WHERE id=p_id RETURNING id INTO v_id; END IF;
 DELETE FROM schoolnet.project_school WHERE school_id=v_id;
 INSERT INTO schoolnet.project_school SELECT value::bigint,v_id FROM jsonb_array_elements_text(p_data->'projects');
 WHEN 'trainee' THEN
 v_project=(p_data->>'project_id')::bigint; v_school=(p_data->>'school_id')::bigint; PERFORM schoolnet.require_project(p_actor,v_project);
 IF p_id<>0 THEN PERFORM schoolnet.require_project(p_actor,(SELECT project_id FROM schoolnet.trainee WHERE id=p_id)); END IF;
 IF NOT EXISTS(SELECT 1 FROM schoolnet.project_school ps JOIN schoolnet.project p ON p.id=ps.project_id JOIN schoolnet.school s ON s.id=ps.school_id WHERE ps.project_id=v_project AND ps.school_id=v_school AND p.active AND s.active) THEN RAISE EXCEPTION 'Select an active school linked to the active project.'; END IF;
 IF p_id<>0 AND EXISTS(SELECT 1 FROM schoolnet.batch_assignment a JOIN schoolnet.batch b ON b.id=a.batch_id WHERE a.trainee_id=p_id AND b.status IN('Scheduled','In progress')) AND EXISTS(SELECT 1 FROM schoolnet.trainee WHERE id=p_id AND (project_id<>v_project OR school_id<>v_school OR NOT (p_data->>'active')::boolean)) THEN RAISE EXCEPTION 'Trainee has an active scheduled assignment.'; END IF;
 IF nullif(p_data->>'user_id','') IS NOT NULL AND NOT EXISTS(SELECT 1 FROM schoolnet.app_user WHERE id=(p_data->>'user_id')::bigint AND role='Trainee' AND active) THEN RAISE EXCEPTION 'Select an active trainee login.'; END IF;
 IF p_id=0 THEN INSERT INTO schoolnet.trainee(username,name,mobile,email,project_id,school_id,user_id,active) VALUES(lower(btrim(p_data->>'username')),btrim(p_data->>'name'),p_data->>'mobile',p_data->>'email',v_project,v_school,nullif(p_data->>'user_id','')::bigint,(p_data->>'active')::boolean) RETURNING id INTO v_id;
 ELSE UPDATE schoolnet.trainee SET username=lower(btrim(p_data->>'username')),name=btrim(p_data->>'name'),mobile=p_data->>'mobile',email=p_data->>'email',project_id=v_project,school_id=v_school,user_id=nullif(p_data->>'user_id','')::bigint,active=(p_data->>'active')::boolean,updated_at=now() WHERE id=p_id RETURNING id INTO v_id; END IF;
 WHEN 'user' THEN
 IF p_id=0 THEN INSERT INTO schoolnet.app_user(username,name,password_hash,role,active) VALUES(lower(btrim(p_data->>'username')),p_data->>'name',p_data->>'password_hash',p_data->>'role',(p_data->>'active')::boolean) RETURNING id INTO v_id;
 ELSE
 IF p_id=p_actor AND (p_data->>'role'<>'Administrator' OR NOT (p_data->>'active')::boolean) THEN RAISE EXCEPTION 'You cannot remove your own administrator access.'; END IF;
 IF EXISTS(SELECT 1 FROM schoolnet.trainee WHERE user_id=p_id) AND p_data->>'role'<>'Trainee' THEN RAISE EXCEPTION 'This login is linked to a trainee.'; END IF;
 UPDATE schoolnet.app_user SET username=lower(btrim(p_data->>'username')),name=p_data->>'name',role=p_data->>'role',active=(p_data->>'active')::boolean,
 password_hash=coalesce(nullif(p_data->>'password_hash',''),password_hash),updated_at=now() WHERE id=p_id RETURNING id INTO v_id; END IF;
 DELETE FROM schoolnet.user_project WHERE user_id=v_id;
 INSERT INTO schoolnet.user_project SELECT v_id,value::bigint FROM jsonb_array_elements_text(p_data->'projects');
 WHEN 'template' THEN
 IF jsonb_array_length(p_data->'questions')=0 OR EXISTS(SELECT 1 FROM jsonb_array_elements(p_data->'questions') q WHERE coalesce(btrim(q->>'label'),'')='' OR q->>'type' NOT IN('Rating','Choice','Text') OR (q->>'type'='Choice' AND coalesce(jsonb_array_length(q->'choices'),0)=0)) THEN RAISE EXCEPTION 'Provide valid feedback questions and choice options.'; END IF;
 INSERT INTO schoolnet.feedback_template(name,version_number,source_id,questions) VALUES(p_data->>'name',coalesce((SELECT version_number+1 FROM schoolnet.feedback_template WHERE id=p_id),1),nullif(p_id,0),p_data->'questions') RETURNING id INTO v_id;
 ELSE RAISE EXCEPTION 'Unknown master record.'; END CASE;
 IF v_id IS NULL THEN RAISE EXCEPTION 'Record not found.'; END IF;
 RETURN v_id; END $$;

CREATE OR REPLACE FUNCTION save_plan(p_id bigint,p_data jsonb,p_actor bigint) RETURNS bigint LANGUAGE plpgsql AS $$
DECLARE v_id bigint; n integer; q jsonb; BEGIN
 PERFORM schoolnet.require_admin(p_actor); PERFORM schoolnet.set_actor(p_actor); n=(p_data->>'number_of_days')::integer;
 IF p_id=0 THEN INSERT INTO schoolnet.trainingplan(plan_code,plan_name,number_of_days,description) VALUES(p_data->>'plan_code',p_data->>'plan_name',n,coalesce(p_data->>'description','')) RETURNING training_plan_id INTO v_id;
 ELSE SELECT training_plan_id INTO v_id FROM schoolnet.trainingplan WHERE training_plan_id=p_id AND status='Draft' FOR UPDATE;
 IF v_id IS NULL THEN RAISE EXCEPTION 'Only Draft plans can be edited.'; END IF;
 DELETE FROM schoolnet.trainingplandetails WHERE training_plan_id=v_id;
 UPDATE schoolnet.trainingplan SET plan_code=p_data->>'plan_code',plan_name=p_data->>'plan_name',number_of_days=n,description=coalesce(p_data->>'description',''),updated_at=now() WHERE training_plan_id=v_id; END IF;
 IF p_data ? 'days' AND jsonb_array_length(p_data->'days')<>n THEN RAISE EXCEPTION 'Provide one activity per numbered day.'; END IF;
 FOR i IN 1..n LOOP
 q=p_data->'days'->(i-1);
 INSERT INTO schoolnet.trainingplandetails(training_plan_id,day_number,activity_type,title,topics,instructions,feedback_template_version_id,duration_minutes)
 VALUES(v_id,i,CASE WHEN i IN(1,n) THEN 'Feedback' ELSE 'Classroom training' END,
 coalesce(nullif(q->>'title',''),CASE WHEN i=1 THEN 'Pre form' WHEN i=n THEN 'Feedback' ELSE 'Classroom training day '||i END),
 coalesce(q->>'topics',''),coalesce(q->>'instructions',''),CASE WHEN i IN(1,n) THEN coalesce(nullif(q->>'feedback_template_version_id','')::bigint,nullif(p_data->>'template_id','')::bigint) END,nullif(q->>'duration_minutes','')::integer);
 END LOOP; RETURN v_id; END $$;
CREATE OR REPLACE PROCEDURE publish_plan(p_plan bigint,p_actor bigint) LANGUAGE plpgsql AS $$ DECLARE p trainingplan; BEGIN
 PERFORM schoolnet.require_admin(p_actor); PERFORM schoolnet.set_actor(p_actor);
 SELECT * INTO p FROM schoolnet.trainingplan WHERE training_plan_id=p_plan FOR UPDATE;
 IF p.status IS DISTINCT FROM 'Draft' THEN RAISE EXCEPTION 'Only Draft plans can be published.'; END IF;
 IF (SELECT count(*) FROM schoolnet.trainingplandetails WHERE training_plan_id=p_plan)<>p.number_of_days OR EXISTS(SELECT 1 FROM generate_series(1,p.number_of_days) n WHERE NOT EXISTS(SELECT 1 FROM schoolnet.trainingplandetails d WHERE d.training_plan_id=p_plan AND d.day_number=n)) THEN RAISE EXCEPTION 'Plan has missing or invalid day numbers.'; END IF;
 IF EXISTS(SELECT 1 FROM schoolnet.trainingplandetails WHERE training_plan_id=p_plan AND (btrim(title)='' OR (activity_type='Feedback' AND feedback_template_version_id IS NULL) OR (activity_type='Classroom training' AND (btrim(topics)='' OR feedback_template_version_id IS NOT NULL)))) THEN RAISE EXCEPTION 'Configure feedback templates and classroom topics before publication.'; END IF;
 UPDATE schoolnet.trainingplan SET status='Published',updated_at=now() WHERE training_plan_id=p_plan; END $$;
CREATE OR REPLACE FUNCTION revise_plan(p_plan bigint,p_actor bigint) RETURNS bigint LANGUAGE plpgsql AS $$ DECLARE p trainingplan; v_id bigint; BEGIN
 PERFORM schoolnet.require_admin(p_actor); PERFORM schoolnet.set_actor(p_actor);
 SELECT * INTO p FROM schoolnet.trainingplan WHERE training_plan_id=p_plan FOR UPDATE;
 IF p.status NOT IN('Published','Archived') OR p.training_plan_id IS NULL THEN RAISE EXCEPTION 'Revise a Published or Archived plan.'; END IF;
 PERFORM pg_advisory_xact_lock(hashtext(p.plan_code));
 INSERT INTO schoolnet.trainingplan(plan_code,plan_name,number_of_days,description,version_number,source_training_plan_id)
 SELECT p.plan_code,p.plan_name,p.number_of_days,p.description,max(version_number)+1,p_plan FROM schoolnet.trainingplan WHERE plan_code=p.plan_code RETURNING training_plan_id INTO v_id;
 INSERT INTO schoolnet.trainingplandetails(training_plan_id,day_number,activity_type,title,topics,instructions,feedback_template_version_id,duration_minutes)
 SELECT v_id,day_number,activity_type,title,topics,instructions,feedback_template_version_id,duration_minutes FROM schoolnet.trainingplandetails WHERE training_plan_id=p_plan;
 RETURN v_id; END $$;
CREATE OR REPLACE PROCEDURE archive_plan(p_plan bigint,p_actor bigint) LANGUAGE plpgsql AS $$ BEGIN
 PERFORM schoolnet.require_admin(p_actor); PERFORM schoolnet.set_actor(p_actor);
 UPDATE schoolnet.trainingplan SET status='Archived',updated_at=now() WHERE training_plan_id=p_plan AND status='Published';
 IF NOT FOUND THEN RAISE EXCEPTION 'Only Published plans can be archived.'; END IF; END $$;

CREATE OR REPLACE FUNCTION save_batch(p_id bigint,p_data jsonb,p_actor bigint) RETURNS bigint LANGUAGE plpgsql AS $$ DECLARE p trainingplan; b batch; v_id bigint; BEGIN
 PERFORM schoolnet.set_actor(p_actor); PERFORM schoolnet.require_project(p_actor,(p_data->>'project_id')::bigint);
 SELECT * INTO p FROM schoolnet.trainingplan WHERE training_plan_id=(p_data->>'training_plan_id')::bigint FOR SHARE;
 IF p.status IS DISTINCT FROM 'Published' THEN RAISE EXCEPTION 'Select a Published training plan.'; END IF;
 IF (p_data->>'number_of_days')::integer<>p.number_of_days THEN RAISE EXCEPTION 'Batch duration must match the selected plan.'; END IF;
 IF (p_data->>'end_date')::date<>(p_data->>'start_date')::date+p.number_of_days-1 THEN RAISE EXCEPTION 'End date must match start date and plan duration.'; END IF;
 IF NOT EXISTS(SELECT 1 FROM schoolnet.project_school ps JOIN schoolnet.project pr ON pr.id=ps.project_id JOIN schoolnet.school s ON s.id=ps.school_id WHERE ps.project_id=(p_data->>'project_id')::bigint AND ps.school_id=(p_data->>'school_id')::bigint AND pr.active AND s.active) THEN RAISE EXCEPTION 'Choose an active school linked to this project.'; END IF;
 IF nullif(p_data->>'trainer_id','') IS NOT NULL AND NOT EXISTS(SELECT 1 FROM schoolnet.app_user WHERE id=(p_data->>'trainer_id')::bigint AND role='Trainer' AND active) THEN RAISE EXCEPTION 'Choose an active trainer.'; END IF;
 IF p_id=0 THEN INSERT INTO schoolnet.batch(code,name,project_id,school_id,training_plan_id,number_of_days,start_date,end_date,trainer_id)
 VALUES(p_data->>'code',p_data->>'name',(p_data->>'project_id')::bigint,(p_data->>'school_id')::bigint,p.training_plan_id,p.number_of_days,(p_data->>'start_date')::date,(p_data->>'end_date')::date,nullif(p_data->>'trainer_id','')::bigint) RETURNING id INTO v_id;
 ELSE SELECT * INTO b FROM schoolnet.batch WHERE id=p_id FOR UPDATE; PERFORM schoolnet.require_project(p_actor,b.project_id);
 IF b.status IS DISTINCT FROM 'Draft' THEN RAISE EXCEPTION 'Only Draft batches can be edited.'; END IF;
 IF EXISTS(SELECT 1 FROM schoolnet.batch_assignment a JOIN schoolnet.trainee t ON t.id=a.trainee_id WHERE a.batch_id=p_id AND (t.project_id<>(p_data->>'project_id')::bigint OR t.school_id<>(p_data->>'school_id')::bigint OR NOT t.active)) THEN RAISE EXCEPTION 'Roster does not match the selected project and school.'; END IF;
 IF EXISTS(SELECT 1 FROM schoolnet.attendance a JOIN schoolnet.batch_assignment ba ON ba.id=a.assignment_id WHERE ba.batch_id=p_id AND a.status<>'Not marked') OR EXISTS(SELECT 1 FROM schoolnet.feedback_submission f JOIN schoolnet.batch_assignment ba ON ba.id=f.assignment_id WHERE ba.batch_id=p_id) THEN RAISE EXCEPTION 'Training records exist; batch setup is locked.'; END IF;
 IF b.training_plan_id<>p.training_plan_id THEN DELETE FROM schoolnet.attendance WHERE assignment_id IN(SELECT id FROM schoolnet.batch_assignment WHERE batch_id=p_id); END IF;
 UPDATE schoolnet.batch SET code=p_data->>'code',name=p_data->>'name',project_id=(p_data->>'project_id')::bigint,school_id=(p_data->>'school_id')::bigint,training_plan_id=p.training_plan_id,number_of_days=p.number_of_days,start_date=(p_data->>'start_date')::date,end_date=(p_data->>'end_date')::date,trainer_id=nullif(p_data->>'trainer_id','')::bigint,updated_at=now() WHERE id=p_id; v_id=p_id;
 INSERT INTO schoolnet.attendance(assignment_id,training_plan_detail_id) SELECT a.id,d.training_plan_detail_id FROM schoolnet.batch_assignment a CROSS JOIN schoolnet.trainingplandetails d WHERE a.batch_id=p_id AND d.training_plan_id=p.training_plan_id ON CONFLICT DO NOTHING;
 PERFORM schoolnet.check_overlap(v_id); END IF; RETURN v_id; END $$;
CREATE OR REPLACE PROCEDURE assign_trainees(p_batch bigint,p_trainees bigint[],p_actor bigint) LANGUAGE plpgsql AS $$ DECLARE b batch; t trainee; aid bigint; BEGIN
 PERFORM schoolnet.set_actor(p_actor); SELECT * INTO b FROM schoolnet.batch WHERE id=p_batch FOR UPDATE; PERFORM schoolnet.require_project(p_actor,b.project_id);
 IF b.status IS DISTINCT FROM 'Draft' THEN RAISE EXCEPTION 'Roster can only be changed in Draft batches.'; END IF;
 FOR t IN SELECT * FROM schoolnet.trainee WHERE id=ANY(p_trainees) ORDER BY id FOR UPDATE LOOP
 IF NOT t.active OR t.project_id<>b.project_id OR t.school_id<>b.school_id THEN RAISE EXCEPTION 'Trainee % is not eligible for this batch.',t.name; END IF;
 INSERT INTO schoolnet.batch_assignment(batch_id,trainee_id,project_id,school_id,assigned_by) VALUES(p_batch,t.id,t.project_id,t.school_id,p_actor) RETURNING id INTO aid;
 INSERT INTO schoolnet.attendance(assignment_id,training_plan_detail_id) SELECT aid,training_plan_detail_id FROM schoolnet.trainingplandetails WHERE training_plan_id=b.training_plan_id;
 END LOOP;
 IF (SELECT count(*) FROM schoolnet.trainee WHERE id=ANY(p_trainees))<>cardinality(p_trainees) THEN RAISE EXCEPTION 'Duplicate or unknown trainee selected.'; END IF;
 PERFORM schoolnet.check_overlap(p_batch); END $$;
CREATE OR REPLACE PROCEDURE remove_assignment(p_assignment bigint,p_actor bigint) LANGUAGE plpgsql AS $$ DECLARE b batch; BEGIN
 PERFORM schoolnet.set_actor(p_actor); SELECT ba.* INTO b FROM schoolnet.batch ba JOIN schoolnet.batch_assignment a ON a.batch_id=ba.id WHERE a.id=p_assignment FOR UPDATE OF ba; PERFORM schoolnet.require_project(p_actor,b.project_id);
 IF b.status IS DISTINCT FROM 'Draft' THEN RAISE EXCEPTION 'Only Draft rosters can change.'; END IF;
 IF EXISTS(SELECT 1 FROM schoolnet.attendance WHERE assignment_id=p_assignment AND status<>'Not marked') OR EXISTS(SELECT 1 FROM schoolnet.feedback_submission WHERE assignment_id=p_assignment) THEN RAISE EXCEPTION 'Assignment has training history.'; END IF;
 DELETE FROM schoolnet.attendance WHERE assignment_id=p_assignment; DELETE FROM schoolnet.batch_assignment WHERE id=p_assignment; END $$;
CREATE OR REPLACE PROCEDURE transition_batch(p_batch bigint,p_status text,p_reason text,p_actor bigint) LANGUAGE plpgsql AS $$ DECLARE b batch; today date=(now() AT TIME ZONE 'Asia/Kolkata')::date; BEGIN
 PERFORM schoolnet.set_actor(p_actor,p_reason); SELECT * INTO b FROM schoolnet.batch WHERE id=p_batch FOR UPDATE; PERFORM schoolnet.require_project(p_actor,b.project_id);
 -- Lock trainees in a stable order to serialize scheduling and overlap checks.
 PERFORM t.id FROM schoolnet.trainee t JOIN schoolnet.batch_assignment a ON a.trainee_id=t.id WHERE a.batch_id=p_batch ORDER BY t.id FOR UPDATE OF t;
 CASE p_status
 WHEN 'Scheduled' THEN
 IF b.status<>'Draft' OR b.trainer_id IS NULL OR NOT EXISTS(SELECT 1 FROM schoolnet.batch_assignment WHERE batch_id=p_batch) THEN RAISE EXCEPTION 'Scheduling requires a Draft batch, trainer and roster.'; END IF;
 IF NOT EXISTS(SELECT 1 FROM schoolnet.trainingplan WHERE training_plan_id=b.training_plan_id AND status='Published') THEN RAISE EXCEPTION 'Selected plan must be Published.'; END IF;
 IF NOT EXISTS(SELECT 1 FROM schoolnet.project_school ps JOIN schoolnet.project p ON p.id=ps.project_id JOIN schoolnet.school s ON s.id=ps.school_id WHERE ps.project_id=b.project_id AND ps.school_id=b.school_id AND p.active AND s.active) OR EXISTS(SELECT 1 FROM schoolnet.batch_assignment a JOIN schoolnet.trainee t ON t.id=a.trainee_id WHERE a.batch_id=b.id AND (NOT t.active OR t.project_id<>b.project_id OR t.school_id<>b.school_id)) OR NOT EXISTS(SELECT 1 FROM schoolnet.app_user WHERE id=b.trainer_id AND role='Trainer' AND active) THEN RAISE EXCEPTION 'Project, school, trainer or roster is no longer eligible.'; END IF;
 PERFORM schoolnet.check_overlap(p_batch);
 WHEN 'Draft' THEN
 IF b.status<>'Scheduled' OR today>=b.start_date OR EXISTS(SELECT 1 FROM schoolnet.attendance a JOIN schoolnet.batch_assignment ba ON ba.id=a.assignment_id WHERE ba.batch_id=p_batch AND a.status<>'Not marked') OR EXISTS(SELECT 1 FROM schoolnet.feedback_submission f JOIN schoolnet.batch_assignment ba ON ba.id=f.assignment_id WHERE ba.batch_id=p_batch) THEN RAISE EXCEPTION 'Batch cannot return to Draft after training begins.'; END IF;
 WHEN 'Completed' THEN
 IF b.status NOT IN('Scheduled','In progress') OR today<=b.end_date THEN RAISE EXCEPTION 'Complete the batch only after its end date.'; END IF;
 IF EXISTS(SELECT 1 FROM schoolnet.attendance a JOIN schoolnet.batch_assignment ba ON ba.id=a.assignment_id WHERE ba.batch_id=p_batch AND a.status='Not marked') THEN RAISE EXCEPTION 'Resolve all Not marked attendance before completion.'; END IF;
 WHEN 'Cancelled' THEN
 IF b.status IN('Completed','Cancelled') OR btrim(coalesce(p_reason,''))='' THEN RAISE EXCEPTION 'Cancellation requires a reason and an open batch.'; END IF;
 ELSE RAISE EXCEPTION 'Invalid lifecycle transition.'; END CASE;
 UPDATE schoolnet.batch SET status=CASE WHEN p_status='Scheduled' AND today>=start_date THEN 'In progress' ELSE p_status END,cancellation_reason=CASE WHEN p_status='Cancelled' THEN p_reason ELSE cancellation_reason END,updated_at=now() WHERE id=p_batch; END $$;

CREATE OR REPLACE PROCEDURE save_attendance(p_batch bigint,p_day integer,p_rows jsonb,p_reason text,p_actor bigint) LANGUAGE plpgsql AS $$
DECLARE b batch; d trainingplandetails; r jsonb; old attendance; role_name text; day_date date; today date=(now() AT TIME ZONE 'Asia/Kolkata')::date; BEGIN
 PERFORM schoolnet.set_actor(p_actor,p_reason); role_name=schoolnet.actor_role(p_actor); SELECT * INTO b FROM schoolnet.batch WHERE id=p_batch FOR UPDATE;
 IF NOT schoolnet.can_batch(p_actor,p_batch) OR role_name='Trainee' THEN RAISE EXCEPTION 'Attendance access denied.'; END IF;
 SELECT * INTO d FROM schoolnet.trainingplandetails WHERE training_plan_id=b.training_plan_id AND day_number=p_day;
 IF d.training_plan_detail_id IS NULL THEN RAISE EXCEPTION 'Invalid day number.'; END IF; day_date=b.start_date+p_day-1;
 IF b.status IN('Draft','Cancelled') OR day_date>today THEN RAISE EXCEPTION 'Attendance is unavailable for this batch or future date.'; END IF;
 IF b.status='Completed' AND role_name<>'Administrator' THEN RAISE EXCEPTION 'Completed batch corrections require an administrator.'; END IF;
 FOR r IN SELECT value FROM jsonb_array_elements(p_rows) LOOP
 SELECT a.* INTO old FROM schoolnet.attendance a JOIN schoolnet.batch_assignment ba ON ba.id=a.assignment_id WHERE a.id=(r->>'id')::bigint AND ba.batch_id=p_batch AND a.training_plan_detail_id=d.training_plan_detail_id FOR UPDATE OF a;
 IF old.id IS NULL THEN RAISE EXCEPTION 'Attendance record is outside the selected batch/day.'; END IF;
 IF old.revision<>(r->>'revision')::integer THEN RAISE EXCEPTION 'Attendance changed in another session. Reload before saving.'; END IF;
 IF r->>'status' NOT IN('Present','Absent','Not marked') THEN RAISE EXCEPTION 'Invalid attendance status.'; END IF;
 IF old.status IS DISTINCT FROM r->>'status' OR old.remarks IS DISTINCT FROM coalesce(r->>'remarks','') THEN
 IF r->>'status'='Not marked' THEN RAISE EXCEPTION 'Saved attendance must be Present or Absent.'; END IF;
 IF day_date<today OR b.status='Completed' OR old.status<>'Not marked' THEN
 IF role_name NOT IN('Administrator','Coordinator') OR btrim(coalesce(p_reason,''))='' THEN RAISE EXCEPTION 'Corrections and past entry require a coordinator or administrator and a reason.'; END IF; END IF;
 UPDATE schoolnet.attendance SET status=r->>'status',remarks=coalesce(r->>'remarks',''),marked_by=p_actor,marked_at=now(),revision=revision+1 WHERE id=old.id;
 END IF; END LOOP; END $$;
CREATE OR REPLACE PROCEDURE submit_feedback(p_assignment bigint,p_day integer,p_answers jsonb,p_reason text,p_actor bigint) LANGUAGE plpgsql AS $$
DECLARE b batch; d trainingplandetails; t trainee; qs jsonb; q jsonb; a text; day_date date; existing bigint; BEGIN
 PERFORM schoolnet.set_actor(p_actor,p_reason);
 SELECT ba.* INTO b FROM schoolnet.batch ba JOIN schoolnet.batch_assignment ass ON ass.batch_id=ba.id WHERE ass.id=p_assignment FOR UPDATE OF ba;
 SELECT tr.* INTO t FROM schoolnet.trainee tr JOIN schoolnet.batch_assignment ass ON ass.trainee_id=tr.id WHERE ass.id=p_assignment;
 IF b.id IS NULL OR NOT schoolnet.can_batch(p_actor,b.id) OR NOT coalesce(t.user_id=p_actor OR schoolnet.can_project(p_actor,b.project_id),false) THEN RAISE EXCEPTION 'Feedback access denied.'; END IF;
 SELECT * INTO d FROM schoolnet.trainingplandetails WHERE training_plan_id=b.training_plan_id AND day_number=p_day AND activity_type='Feedback';
 IF d.training_plan_detail_id IS NULL OR b.status IN('Draft','Cancelled') THEN RAISE EXCEPTION 'Feedback unavailable for this day or batch.'; END IF;
 day_date=b.start_date+p_day-1;
 IF (now() AT TIME ZONE 'Asia/Kolkata')::date<>day_date OR t.user_id IS DISTINCT FROM p_actor THEN
 IF NOT schoolnet.can_project(p_actor,b.project_id) OR btrim(coalesce(p_reason,''))='' OR day_date>(now() AT TIME ZONE 'Asia/Kolkata')::date THEN RAISE EXCEPTION 'Late or offline feedback requires authorized staff and a reason; future submissions are blocked.'; END IF; END IF;
 SELECT id INTO existing FROM schoolnet.feedback_submission WHERE assignment_id=p_assignment AND training_plan_detail_id=d.training_plan_detail_id;
 IF existing IS NOT NULL AND (NOT schoolnet.can_project(p_actor,b.project_id) OR btrim(coalesce(p_reason,''))='') THEN RAISE EXCEPTION 'Final submission is locked. Authorized corrections require a reason.'; END IF;
 IF b.status='Completed' AND schoolnet.actor_role(p_actor)<>'Administrator' THEN RAISE EXCEPTION 'Completed batch corrections require an administrator.'; END IF;
 SELECT questions INTO qs FROM schoolnet.feedback_template WHERE id=d.feedback_template_version_id;
 FOR q IN SELECT value FROM jsonb_array_elements(qs) LOOP
 a=btrim(coalesce(p_answers->>(q->>'id'),''));
 IF coalesce((q->>'required')::boolean,false) AND a='' THEN RAISE EXCEPTION 'Answer required: %',q->>'label'; END IF;
 IF a<>'' AND q->>'type'='Rating' AND a NOT IN('1','2','3','4','5') THEN RAISE EXCEPTION 'Ratings must be between 1 and 5.'; END IF;
 IF a<>'' AND q->>'type'='Choice' AND NOT (q->'choices') @> to_jsonb(ARRAY[a]) THEN RAISE EXCEPTION 'Select a valid answer option.'; END IF;
 END LOOP;
 INSERT INTO schoolnet.feedback_submission(assignment_id,training_plan_detail_id,template_version_id,answers,submitted_by,reason)
 VALUES(p_assignment,d.training_plan_detail_id,d.feedback_template_version_id,p_answers,p_actor,p_reason)
 ON CONFLICT(assignment_id,training_plan_detail_id) DO UPDATE SET answers=excluded.answers,submitted_by=excluded.submitted_by,submitted_at=now(),reason=excluded.reason;
 END $$;
INSERT INTO schema_version(version) VALUES(1) ON CONFLICT DO NOTHING;
